String name = "abcd";
int[] data = {7, 2, 14, 9};
for(int i = 0; i < data.length; i++){
  if( i % 2 == 0 ){
    if( name.charAt(i) < 'c' )
      data[i] /= 3;
    else
      data[i] -= name.charAt(i) - 'a';
  } else {
      data[i] += name.charAt(i) - 'a';
  }
}
for(int i : data )
  System.out.print( i );

