public int utpb(String val){
  int res = 1;
  for(int i = 0; i < val.length(); i += 2){
    char c = val.charAt(i);
    switch (c) {
      case 'b': res *= 2; break;
      case 'd': res += 2; break;
      case 'c': res = res * res; break;
      case 'a': res++; break;
      default:
        res = res / 3;
    }
  }
  return res;
}

